    func testTakenSquareIgnored() {
        let scenario = Scenario(region: "en-US")
        scenario.launch(fresh: true)
        scenario.tap("square-4")
        scenario.tap("square-4")
        scenario.expectShows("square-4", "X")
        scenario.expectShows("turn", "O's turn")
        scenario.tap("square-2")
        scenario.expectShows("square-2", "O")
